//! Settings window of Bento Desk. Separate process, started on demand by the
//! resident app and closed with its window: it uses no memory at rest.

#![windows_subsystem = "windows"]
// Hand-written code has no `unsafe`; only the code generated by the Slint
// compiler (module `ui`) is allowed to use it.
#![deny(unsafe_code)]

#[allow(
    unsafe_code,
    clippy::all,
    clippy::pedantic,
    clippy::unwrap_used,
    clippy::expect_used
)]
#[allow(clippy::undocumented_unsafe_blocks, missing_debug_implementations)]
mod ui {
    slint::include_modules!();
}

pub use ui::*;

mod bridge;
mod keys;
mod text;

use std::cell::RefCell;
use std::rc::Rc;

use anyhow::Context;
use bento_win::window::Hwnd;
use raw_window_handle::{HasWindowHandle, RawWindowHandle};
use slint::ComponentHandle;

use crate::text::T;

const INSTANCE: &str = "Local\\BentoDesk.Settings";

#[derive(Debug, Default)]
struct Args {
    section: Option<String>,
    fence: Option<u64>,
}

fn parse_args(mut it: impl Iterator<Item = String>) -> Args {
    let mut a = Args::default();
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--section" => a.section = it.next(),
            "--fence" => a.fence = it.next().and_then(|v| v.parse().ok()),
            _ => {}
        }
    }
    a
}

/// Brings the window of an already running instance to the front.
fn focus_existing() {
    for lang in [bento_core::i18n::Lang::Fr, bento_core::i18n::Lang::En] {
        if let Some(h) = bento_win::window::find_window_by_title(T::WindowTitle.get(lang)) {
            h.restore_and_focus();
            return;
        }
    }
}

/// Native handle of the Slint window, once it is shown.
fn native_handle(ui: &MainWindow) -> Option<Hwnd> {
    let handle = ui.window().window_handle();
    let raw = handle.window_handle().ok()?.as_raw();
    match raw {
        RawWindowHandle::Win32(w) => Some(Hwnd(w.hwnd.get())),
        _ => None,
    }
}

/// Dark title bar when Windows uses the dark theme, Mica where available
/// (Windows 11 22H2 and later; ignored by Windows 10).
fn style_frame(hwnd: Hwnd) {
    bento_win::dwm::set_dark(hwnd, !bento_win::system::apps_use_light_theme());
    bento_win::dwm::set_backdrop(hwnd, bento_win::dwm::Backdrop::Mica);
    bento_win::dwm::set_round_corners(hwnd);
}

fn main() -> anyhow::Result<()> {
    let args = parse_args(std::env::args().skip(1));
    let Some(_instance) =
        bento_win::system::SingleInstance::acquire(INSTANCE).context("single instance mutex")?
    else {
        focus_existing();
        return Ok(());
    };
    // File dialogs need an STA; OLE also serves winit's drag and drop.
    let _com = bento_win::com::ComApartment::ole_sta().context("COM initialization")?;
    let paths = bento_config::Paths::resolve().context("data folder")?;
    let config = bento_config::load_config(&paths);
    let state = bento_config::load_state(&paths);
    let lang = config
        .general
        .language
        .resolve(bento_win::system::ui_language());

    let ui = MainWindow::new().context("settings window")?;
    bridge::apply_language(lang);
    let shared: bridge::Shared =
        Rc::new(RefCell::new(bridge::Ctl::new(paths, config, state, lang)));
    {
        let mut ctl = shared.borrow_mut();
        bridge::push_all(&mut ctl, &ui);
        if let Some(section) = &args.section {
            bridge::open_section(&ctl, &ui, section, args.fence);
        }
    }
    bridge::install(&ui, &shared);
    ui.show().context("show window")?;
    if let Some(hwnd) = native_handle(&ui) {
        style_frame(hwnd);
        shared.borrow_mut().owner = hwnd;
    }
    slint::run_event_loop().context("event loop")?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn arguments() {
        let a = parse_args(
            ["--section", "appearance", "--fence", "12"]
                .into_iter()
                .map(String::from),
        );
        assert_eq!(a.section.as_deref(), Some("appearance"));
        assert_eq!(a.fence, Some(12));
        let a = parse_args(std::iter::empty());
        assert!(a.section.is_none() && a.fence.is_none());
    }
}
